        self.assertEqual(next_run("* * * * *", at(2026, 1, 1, 10, 0, 30, 500)), at(2026, 1, 1, 10, 1))

    def test_fractional_second_on_minute_boundary_is_excluded(self):
        self.assertEqual(next_run("0 * * * *", at(2026, 1, 1, 10, 0, 0, 5)), at(2026, 1, 1, 11, 0))

    def test_rolls_over_year(self):
        self.assertEqual(next_run("0 0 1 1 *", at(2026, 12, 31, 23, 59)), at(2027, 1, 1, 0, 0))

