    def test_double_space_rejected(self):
        with self.assertRaises(ValueError):
            next_run("0  * * * *", at(2026, 1, 1))

    def test_tab_separator_rejected(self):
        with self.assertRaises(ValueError):
            next_run("0\t* * * *", at(2026, 1, 1))

    def test_leading_and_trailing_space_rejected(self):
        with self.assertRaises(ValueError):
            next_run(" 0 * * * *", at(2026, 1, 1))
        with self.assertRaises(ValueError):
            next_run("0 * * * * ", at(2026, 1, 1))

    # Rule: field ranges.
    def test_minute_out_of_range(self):
        with self.assertRaises(ValueError):
            next_run("60 * * * *", at(2026, 1, 1))

    def test_hour_out_of_range(self):
        with self.assertRaises(ValueError):
            next_run("0 24 * * *", at(2026, 1, 1))

    def test_dom_zero_rejected(self):
        with self.assertRaises(ValueError):
